// ── URLSearchParams — safe query string building ──
const params = new URLSearchParams({
    category: 'electronics',
    sort:     'price_asc',
    page:     '2',
    q:        'USB-C hub',  // spaces + special chars → encoded automatically
});
console.log(params.toString());
// → category=electronics&sort=price_asc&page=2&q=USB-C+hub

const url = `https://api.example.com/products?${params}`;

// ── URL class for full URLs ──
const u = new URL('https://api.github.com/search/repositories');
u.searchParams.set('q', 'react language:typescript');
u.searchParams.set('sort', 'stars');
u.searchParams.set('per_page', '10');
console.log(u.toString());
// → https://api.github.com/search/repositories?q=react+language%3Atypescript&sort=stars&per_page=10

// ── Request headers ──
const res = await fetch(url, {
    headers: {
        'Accept':          'application/json',
        'Authorization':   'Bearer my-token',
        'X-Client-Version': '1.0.0',
        // 'Content-Type' — only needed for POST/PUT/PATCH with a body
    },
});

// ── Reading response headers ──
console.log('Content-Type:',  res.headers.get('content-type'));
console.log('Rate Limit:',    res.headers.get('x-ratelimit-limit'));
console.log('Remaining:',     res.headers.get('x-ratelimit-remaining'));
console.log('Reset Time:',    res.headers.get('x-ratelimit-reset'));
console.log('Request ID:',    res.headers.get('x-request-id'));  // for support tickets

// ── Pagination via Link header (GitHub style) ──
const link = res.headers.get('link');
// → '<https://api.example.com/users?page=3>; rel="next", <...>; rel="last"'
if (link) {
    const nextMatch = link.match(/<([^>]+)>; rel="next"/);
    const nextUrl   = nextMatch?.[1];
    console.log('Next page:', nextUrl);
}
